def sum_subarray_minimums(arr):
 arr=[-1]+arr+[-1];stack=[];answer=0
 for i,value in enumerate(arr):
  while stack and arr[stack[-1]]>value:
   j=stack.pop();answer+=arr[j]*(j-stack[-1])*(i-j)
  stack.append(i)
 return answer%1000000007

